import {countryNames,latestEvaluation,countrySeries,trendSegments} from './world-perspective.mjs';
const esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const say=(l,en,hi)=>l==='hi'?hi:en;
export const topLifeEvaluations=countryNames.map(name=>({name,row:latestEvaluation(name)})).filter(x=>x.row).toSorted((a,b)=>b.row[1]-a.row[1]||a.name.localeCompare(b.name)).slice(0,10);
export function rankedCountryRows(selected='India',expanded=false,l='en'){
 return topLifeEvaluations.slice(0,expanded?10:5).map(({name,row},i)=>`<button class="mh-country-row" data-country="${esc(name)}" aria-controls="mh-country-detail"><span class="mh-country-rank">${i===0?'✧':i+1}</span><span class="mh-country-name">${esc(name)}</span><span class="mh-country-value">${row[1].toFixed(2)}<small> / 10</small></span><span class="mh-country-meter" aria-hidden="true"><i style="width:${row[1]*10}%"></i></span><span class="mh-sr">${say(l,'Explore this country','यह देश देखें')}</span></button>`).join('');
}
export function countryDetail(name='India',l='en'){
 const latest=latestEvaluation(name);if(!latest)return `<p>${say(l,'No published data for this country.','इस देश के प्रकाशित आँकड़े उपलब्ध नहीं हैं।')}</p>`;
 const rows=countrySeries(name),x=year=>44+(year-2020)*57,y=value=>185-value*14;
 const chart=`<svg viewBox="0 0 366 225" role="img" aria-label="${say(l,'Three-year life evaluation averages. Exact values follow in the data table.','तीन-वर्षीय life evaluation averages। नीचे data table में सभी मान हैं।')}">${[0,5,10].map(n=>`<path d="M44 ${y(n)}H329" stroke="#dce8ee" stroke-dasharray="3 5"/><text x="28" y="${y(n)+5}" text-anchor="end">${n}</text>`).join('')}${trendSegments(rows).map(segment=>`${segment.length>1?`<polyline points="${segment.map(r=>`${x(r[0])},${y(r[1])}`).join(' ')}" fill="none" stroke="#5699b9" stroke-width="3"/>`:''}${segment.map(r=>`<circle cx="${x(r[0])}" cy="${y(r[1])}" r="5" fill="#5699b9" stroke="white" stroke-width="2"><title>${r[0]-2}–${r[0]}: ${r[1].toFixed(2)}</title></circle>`).join('')}`).join('')}${[2020,2021,2022,2023,2024,2025].map(year=>`<text x="${x(year)}" y="214" text-anchor="middle">${String(year).slice(2)}</text>`).join('')}</svg>`;
 return `<div class="mh-country-summary"><div><h4>${esc(name)}</h4><p>${say(l,'2023–2025 average','2023–2025 का औसत')}</p></div><strong>${latest[1].toFixed(2)}<small> / 10</small></strong></div>${chart}<p class="mh-country-caption">${say(l,'Life evaluation · Three-year averages<br>Axis: final survey year, 2020–2025','Life evaluation · तीन-वर्षीय औसत<br>अक्ष: अंतिम survey वर्ष, 2020–2025')}</p><details class="mh-country-data"><summary>${say(l,'See exact values & uncertainty','सही मान और अनिश्चितता देखें')}</summary><p>${say(l,'0 = worst possible life; 10 = best possible life. Adjacent periods overlap. Small differences can fall within sampling uncertainty.','0 = सबसे खराब संभव जीवन; 10 = सबसे अच्छा संभव जीवन। पास-पास की अवधियाँ overlap करती हैं। छोटे अंतर sampling uncertainty में आ सकते हैं।')}</p><table><caption>${say(l,'Mean and 95% confidence interval','औसत और 95% विश्वास अंतराल')}</caption><thead><tr><th>${say(l,'Period','अवधि')}</th><th>${say(l,'Average','औसत')}</th><th>95% CI</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${r[0]-2}–${r[0]}</td><td>${r[1].toFixed(3)}</td><td>${r[2].toFixed(3)}–${r[3].toFixed(3)}</td></tr>`).join('')}</tbody></table></details>`;
}
export function globalDiscovery(l='en'){
 return `<section class="mh-global" id="mh-global-discovery"><div class="mh-section-heading"><div><p class="mh-kicker">${say(l,'A WIDER PERSPECTIVE','दुनिया से एक नज़रिया')}</p><h2>${say(l,'Different places.<br>Different experiences.','अलग देश।<br>अलग अनुभव।')}</h2></div><p>${say(l,'How do people rate their lives?<br>Choose a country and explore.','लोग अपनी ज़िंदगी को कैसे देखते हैं?<br>एक देश चुनकर देखें।')}</p></div><div class="mh-global-grid"><article class="mh-country-card mh-ranking-card"><header><span class="mh-country-icon" aria-hidden="true">↗</span><div><h3>${say(l,'Higher life evaluations','ज़िंदगी की बेहतर रेटिंग')}</h3><p>${say(l,'Published averages · 2023–2025','प्रकाशित औसत · 2023–2025')}</p></div><span class="mh-top-count">10<small>${say(l,'places','देश / क्षेत्र')}</small></span></header><div id="mh-country-rows">${rankedCountryRows('India',false,l)}</div><button class="mh-country-more" data-country-expand aria-expanded="false" aria-controls="mh-country-rows">${say(l,'Explore all 10','सभी 10 देखें')} <span aria-hidden="true">↓</span></button></article><article class="mh-country-card mh-country-explorer"><header><span class="mh-country-icon" aria-hidden="true">◎</span><div><h3>${say(l,'Look a little closer','थोड़ा और करीब से देखें')}</h3><p>${say(l,'A country, over time','एक देश, समय के साथ')}</p></div></header><label class="mh-country-picker"><span class="mh-sr">${say(l,'Choose a country or territory','देश या क्षेत्र चुनें')}</span><select id="mh-country-select" aria-label="${say(l,'Choose a country or territory','देश या क्षेत्र चुनें')}">${countryNames.map(name=>`<option value="${esc(name)}"${name==='India'?' selected':''}>${esc(name)}</option>`).join('')}</select></label><div id="mh-country-detail">${countryDetail('India',l)}</div></article></div><p class="mh-global-source">${say(l,'Source: World Happiness Report 2026 · Gallup World Poll.','स्रोत: World Happiness Report 2026 · Gallup World Poll।')} <a href="https://www.worldhappiness.report/data-sharing/" target="_blank" rel="noopener">${say(l,'Data & methodology','डेटा और पद्धति')} ↗</a></p><div class="mh-global-bridge"><p>${say(l,'A country average cannot tell your story.<br><strong>Your check-in starts with you.</strong>','देश का औसत आपकी कहानी नहीं बताता।<br><strong>आपका check-in आपसे शुरू होता है।</strong>')}</p><button class="mh-secondary" data-action="begin">${say(l,'Start My Test','अपना टेस्ट शुरू करें')} →</button></div><p class="mh-global-limit">${say(l,'These are life evaluations, not mental-health or personality scores. They do not affect your report.','ये life evaluation averages हैं, mental-health या personality scores नहीं। इनका आपकी report पर असर नहीं होता।')}</p><span class="mh-sr" id="mh-country-update" aria-live="polite"></span></section>`;
}
export function bindGlobalDiscovery(root,l='en'){
 const section=root.querySelector('#mh-global-discovery');if(!section)return;let expanded=false,selected='India';const select=section.querySelector('#mh-country-select');
 function update(name){if(!latestEvaluation(name))return;selected=name;select.value=name;section.querySelector('#mh-country-detail').innerHTML=countryDetail(name,l);section.querySelector('#mh-country-update').textContent=say(l,`Showing life evaluations for ${name}.`,`${name} के life evaluation averages दिख रहे हैं।`);}
 select.addEventListener('change',()=>update(select.value));
 section.addEventListener('click',e=>{const row=e.target.closest('[data-country]');if(row){const name=row.dataset.country;update(name);section.querySelector(`[data-country="${CSS.escape(name)}"]`)?.focus({preventScroll:true});return;}const button=e.target.closest('[data-country-expand]');if(button){expanded=!expanded;section.querySelector('#mh-country-rows').innerHTML=rankedCountryRows(selected,expanded,l);button.setAttribute('aria-expanded',String(expanded));button.textContent=say(l,expanded?'Show five places ↑':'Explore all 10 ↓',expanded?'पाँच देश दिखाएँ ↑':'सभी 10 देखें ↓');}});
}
export function feelingIcon(key){const paths={stress:'M5 12c0-5 14-5 14 0s-14 5-14 0m4-7c-4 6 3 14 6 14M4 20h16',mood:'M7 16a5 5 0 1 1 10 0M4 20h16M12 2v2M4 6l2 2m14-2-2 2',worry:'M5 4h14v12H9l-4 4V4m4 5h6m-6 3h4',anger:'M4 9c4-6 4 6 8 0s4 6 8 0M4 16c4-6 4 6 8 0s4 6 8 0',relationships:'M4 7a4 4 0 0 1 8-2 4 4 0 0 1 8 2c0 5-8 11-8 11S4 12 4 7Z',sleep:'M18 3A9 9 0 1 0 21 16 8 8 0 0 1 18 3Z'};return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[key]||paths.stress}"/></svg>`;}
